/**
 * Single source of truth for every translatable string, in both languages.
 *
 * Nothing else should hold UI copy: pages and components read from here through
 * `t("key")`, so a string exists in exactly one place and can never be present
 * in one language and missing in the other.
 *
 * `src/i18n/ne.json` and `src/i18n/en.json` are generated from this file and
 * must not be edited by hand. Run `npm run i18n` after changing anything here
 * (`npm run dev` and `npm run build` do it for you).
 *
 * Keys are dotted paths, grouped by the leading segment. `{{name}}` marks an
 * interpolated value supplied at the call site.
 */

/** A value in both supported languages. */
export type Bi<T> = { ne: T; en: T };

/** A question/answer pair used by the SEO FAQ blocks. */
export type FaqItem = { q: string; a: string };

export type Translatable = Bi<string> | Bi<string[]> | Bi<FaqItem[]>;

