  "panchanga.hora.one_week": { ne: "एक हप्ता,", en: "One week," },
  "panchanga.hora.unbroken_hora": { ne: "निरन्तर होरा", en: "unbroken hora" },
  "panchanga.hora.intro": {
    ne: "हरेक वलय एउटै दिन हो — सात ग्रहले पालो–पालोमा शासन गर्ने चौबीस <1>होरा</1>। सूर्योदयपछिको <2>पहिलो</2> होराको ग्रहले दिनको नाम दिन्छ। गणना कहिल्यै रोकिँदैन: <3>आइतबार</3>को अन्तिम होरा <4>सोम</4>मा गुड्छ र <5>सोमबार</5> खोल्छ। केन्द्रबाट बाहिरतिर — <6>आदित्य → शनि</6> — हप्ताभरि सर्पिल अनुसरण गर्नुहोस्।",
    en: "Each ring is one day — twenty-four <1>horas</1> ruled in turn by the seven planets. The planet of the <2>first</2> hora after sunrise gives the day its name. The count never stops: the last hora of <3>Sunday</3> rolls into <4>Monday</4> and opens <5>Monday</5>. Follow the spiral from the centre outward — <6>Sun → Saturn</6> — across the week.",
  },
  "panchanga.hora.seven_days": { ne: "सात दिन · भित्र → बाहिर", en: "Seven days · inner → outer" },

