  "rashifal.tabs.yearly": { ne: "वार्षिक", en: "Yearly" },
  "rashifal.lucky_color": { ne: "शुभ रंग", en: "Lucky colour" },
  "rashifal.lucky_number": { ne: "शुभ अंक", en: "Lucky number" },
  "rashifal.moon_at_sunrise": { ne: "सूर्योदयको चन्द्र: {{sign}}", en: "Moon at sunrise: {{sign}}" },
  "rashifal.method_note": {
    ne: "स्थानीय सूर्योदयमा सर्भरमा गणना — नौ ग्रहको गोचर र वेध, गोचर कुण्डलीको अष्टकवर्ग, लग्न/चन्द्र/सूर्यको सुदर्शन चक्र, नवतारा चन्द्रबल, मूर्ति निर्णय र राशिस्वामीको स्थिति। शुभ रंग, अंक, दिशा र होरा राशिस्वामीबाट।",
    en: "Computed on the server at your local sunrise — nine-graha gochar with vedha, Ashtakavarga of the transit chart, the lagna / Chandra / Surya Sudarshana chakras, navatara chandrabala, Moorti nirnaya and the sign lord's own condition. Lucky colour, number, direction and hora all follow the sign lord.",
  },
