  "kundali.x.shanti_basis_note": {
    ne: "गणना शास्त्रीय ४-चरण विधिमा आधारित छ — (१) वर्तमान दशा/अन्तर्दशा स्वामी ६,८,१२ भाव वा मारकको स्वामी, नीच वा अस्त छ कि, (२) लग्नेश/पञ्चमेश/नवमेश कमजोर छ कि, (३) राहु/केतु/शनिले शुभ ग्रह वा भाव पीडित गरेका छन् कि, र (४) शनिको साढेसाती/ढैया गोचर चलिरहेको छ कि। यो सामान्य मार्गदर्शन हो — विधिवत् उपायका लागि योग्य ज्योतिषीसँग परामर्श गर्नुहोस्।",
    en: "The calculation follows the classical 4-step process — (1) is the current dasha/antardasha lord a 6th/8th/12th or maraka house lord, debilitated, or combust, (2) is the Lagnesha/5th/9th lord weak, (3) are Rahu/Ketu/Saturn afflicting a benefic planet or house, and (4) is Saturn transiting Sade Sati/Dhaiya. This is general guidance — consult a qualified astrologer for formal remedies.",
  },
  "kundali.x.shanti_beeja_mantra_column": { ne: "बीज मन्त्र", en: "Beeja mantra" },
  "kundali.x.shanti_beeja_mantra_heading": { ne: "बीज मन्त्र", en: "Beeja Mantra" },
  "kundali.x.shanti_daan_column": { ne: "दान", en: "Daan" },
  "kundali.x.shanti_deity": { ne: "अधिदेवता", en: "Deity" },
  "kundali.x.shanti_disclaimer": {
    ne: "सूचना: माथिका विवरण शास्त्रीय नवग्रह शान्ति परम्परामा आधारित छन्। रत्नधारण वा विधिवत् हवन गर्नुअघि योग्य ज्योतिषी/पुरोहितसँग परामर्श गर्नुहोस्।",
    en: "Note: the details above are based on the classical Navagraha Shanti tradition. Consult a qualified astrologer/priest before wearing gems or performing a formal homa.",
  },
