  /* ── panchak ─────────────────────────────────────────────────────────── */
  "panchak.title": { ne: "पञ्चक पात्रो {{year}}", en: "Panchak Patro {{year}}" },
  "panchak.subtitle": {
    ne: "वैदिक ज्योतिष र सूर्य सिद्धान्तमा आधारित पञ्चक काल र मुहूर्त विवरण",
    en: "Panchak periods and moment details based on Vedic jyotish and Surya Siddhanta",
  },
  "panchak.intro": {
    ne: "पञ्चक भन्नाले चन्द्रमाले पाँच विशेष नक्षत्रहरू (धनिष्ठाको उत्तरार्ध, शतभिषा, पूर्वाभाद्रपद, उत्तराभाद्रपद र रेवती) पार गर्ने पाँच दिनको अवधिलाई बुझिन्छ। वैदिक ज्योतिष अनुसार, यस अवधिमा केही निश्चित कार्यहरू नगर्न सल्लाह दिइन्छ किनभने पञ्चक कालमा गरिएका कार्यहरू पाँच पटक दोहोरिने धार्मिक विश्वास रहेको छ।",
    en: "Panchak is the roughly five-day span while the Moon transits the last half of Dhanishta, Shatabhisha, Purva Bhadrapada, Uttara Bhadrapada, and Revati. Many traditions advise avoiding certain acts during Panchak, believing work done then may repeat fivefold.",
  },
  "panchak.back_home": { ne: "गृहपृष्ठमा फर्कनुहोस्", en: "Back to home" },
  "panchak.year_label": { ne: "वि.सं. वर्ष", en: "B.S. year" },
  "panchak.periods_title": { ne: "{{year}} का पञ्चक अवधिहरू", en: "Panchak windows for {{year}}" },
  "panchak.period_label": { ne: "पञ्चक {{n}}", en: "Panchak {{n}}" },
  "panchak.start_date": { ne: "सुरु हुने मिति", en: "Start" },
  "panchak.end_date": { ne: "समाप्त हुने मिति", en: "End" },
  "panchak.duration": { ne: "अवधि", en: "Duration" },
  "panchak.no_data": {
    ne: "{{year}} का लागि पञ्चक विवरण उपलब्ध छैन।",
    en: "Panchak details for {{year}} are not available yet.",
  },
  "panchak.prohibited_title": { ne: "पञ्चकमा वर्जित गरिएका कार्यहरू", en: "Acts discouraged during Panchak" },
  "panchak.prohibited.south_travel": { ne: "दक्षिण यात्रा", en: "Travel south" },
  "panchak.prohibited.south_travel_desc": {
    ne: "यमराजको दिशाबाट बच्न (Avoiding the direction of Yamaraj)",
    en: "Avoiding the direction of Yama (south)",
  },
  "panchak.prohibited.roof": { ne: "घर छाउनु", en: "Roofing a house" },
  "panchak.prohibited.roof_desc": {
    ne: "नयाँ घरमा छत हाल्नु (Putting the roof on a new house)",
    en: "Placing the roof on a new house",
  },
  "panchak.prohibited.bed": { ne: "खाट/छपरी बुन्नु", en: "Weaving a bed or cot" },
  "panchak.prohibited.bed_desc": {
    ne: "खाट वा कोक्रो बुन्नु वा बनाउनु (Weaving or constructing a bed/cot)",
    en: "Weaving or constructing a bed/cot (charpai)",
  },
  "panchak.prohibited.fuel": { ne: "काठ-दाउरा सञ्चय", en: "Gathering firewood or grass" },
  "panchak.prohibited.fuel_desc": {
    ne: "दाउरा वा घाँस जम्मा गर्नु (Gathering firewood or grass)",
    en: "Stockpiling fuel or fodder",
  },
  "panchak.prohibited.last_rites": { ne: "दाह संस्कार", en: "Last rites" },
  "panchak.prohibited.last_rites_desc": {
    ne: "अन्तिम संस्कार गर्नु (Performing last rites)",
    en: "Performing cremation or final funeral rites",
  },
  "panchak.learn_title": { ne: "पञ्चकको बारेमा बुझ्नुहोस्", en: "Understanding Panchak" },
  "panchak.what_title": { ne: "पञ्चक के हो?", en: "What is Panchak?" },
  "panchak.what_body": {
    ne: "पञ्चक भन्नाले चन्द्रमाले पाँच विशेष नक्षत्रहरू (धनिष्ठाको उत्तरार्ध, शतभिषा, पूर्वाभाद्रपद, उत्तराभाद्रपद र रेवती) पार गर्ने पाँच दिनको अवधिलाई बुझिन्छ। यस अवधिमा दक्षिण यात्रा, तृण सङ्ग्रह, वा घरको छत हाल्ने जस्ता कार्यहरू नगर्न सल्लाह दिइन्छ।",
    en: "Panchak is the five-day lunar window through five special nakshatras (second half of Dhanishta through Revati). Travel south, gathering grass or firewood, and roofing a home are commonly avoided.",
  },
  "panchak.rahita_title": { ne: "पञ्चक रहित मुहूर्तको महत्त्व", en: "Why Panchaka-rahita moment matters" },
  "panchak.rahita_body": {
    ne: "पञ्चक रहित विधिको प्रयोगले विवाह वा मुण्डन जस्ता शुभ कार्यहरू यी 'दोषयुक्त' समयभन्दा बाहिर तय भएको सुनिश्चित गर्दछ, जसले गर्दा कार्यहरू निर्विघ्न सम्पन्न हुन्छन्।",
    en: "Scheduling auspicious rites (vivaha, mundana, etc.) in Panchaka-rahita windows keeps them outside these inauspicious spans so the work may proceed smoothly.",
  },
