  "vastu.plot.footprint_width_label": { ne: "घरको नाप (पूर्व–पश्चिम)", en: "House footprint (East–West)" },
  "vastu.plot.ayadi_disclaimer": {
    ne: "यो परम्परागत विधिको सरलीकृत रूप हो — योग्य वास्तुविद्को सल्लाहको विकल्प होइन।",
    en: "A simplified version of one traditional method — not a substitute for a qualified Vastu consultant.",
  },
  "vastu.plot.ayadi_hasta_label": { ne: "हातमा (क्युबिट)", en: "In hasta (cubits)" },
  "vastu.plot.ayadi_remainder_label": { ne: "शेष", en: "Remainder" },
  "vastu.plot.ayadi_auspicious": { ne: "शुभ शेष", en: "Auspicious remainder" },
  "vastu.plot.ayadi_inauspicious": { ne: "अशुभ शेष", en: "Inauspicious remainder" },
  "vastu.plot.ayadi_suggestion": {
    ne: "बरु {{hasta}} हात (लगभग {{meters}} मि) चौडाइ प्रयोग गरे शुभ शेष पाइन्छ।",
    en: "Try a width of {{hasta}} hasta (~{{meters}} m) instead for an auspicious remainder.",
  },
  "vastu.plot.entrance_heading": { ne: "सुझाव गरिएको प्रवेशद्वार क्षेत्र", en: "Suggested entrance zone" },
  "vastu.plot.entrance_note": {
    ne: "{{wall}} भित्ता, {{corner}} कुनाको नजिक",
    en: "{{wall}} wall, nearer the {{corner}} corner",
  },
  "vastu.plot.entrance_disclaimer": {
    ne: "एउटा सामान्य नियम मात्र — जुनसुकै दिशा भए पनि ठ्याक्कै कुना र ठ्याक्कै बीचमा जोगिनुपर्छ।",
    en: "A general rule of thumb — the exact corner and the exact center are avoided regardless of facing.",
  },

  "vastu.plot.marma_note": {
    ne: "बिन्दुरेखा दुई मुख्य मर्म रेखा (कुनाबाट कुनासम्मको ऱेखा) हुन् — परम्परा अनुसार गह्रौँ खम्बा, भित्ता वा शौचालय यी रेखामाथि नपार्नु राम्रो। यो पूर्ण मर्म/रज्जु प्रणालीको सानो अंश मात्र हो।",
    en: "The dashed lines are the plot's two main marma (energy) lines, corner to corner — traditional guidance keeps heavy pillars, walls, or toilets off them. This shows just the two main diagonals, not the complete traditional marma/rajju system.",
  },

  "vastu.plot.owner_heading": { ne: "मालिक र मिति मिलान", en: "Owner & date compatibility" },
  "vastu.plot.owner_blurb": {
    ne: "आफ्नो प्रोफाइल छान्नुहोस्, अनि घर बनाउन सुरु गर्न सोचेको मिति तपाईंको जन्म नक्षत्रसँग मिल्छ कि मिल्दैन जाँच्नुहोस् — परम्परागत ताराबल विधिबाट।",
    en: "Select your profile, then check whether a date you're considering for starting construction is favorable for your birth star — using the traditional Tara Bala method.",
  },
  "vastu.plot.construction_date_label": { ne: "निर्माण सुरु गर्ने मिति", en: "Construction start date" },
  "vastu.plot.construction_place_label": { ne: "जग्गाको स्थान", en: "Plot's location" },
  "vastu.plot.owner_loading": { ne: "गणना गर्दै…", en: "Calculating…" },
  "vastu.plot.owner_error": {
    ne: "अहिले गणना गर्न सकिएन — पछि फेरि प्रयास गर्नुहोस्।",
    en: "Couldn't calculate this right now — please try again.",
  },
  "vastu.plot.owner_nakshatra_label": { ne: "तपाईंको जन्म नक्षत्र", en: "Your birth Nakshatra" },
  "vastu.plot.construction_result": {
    ne: "छानिएको मितिका लागि यो {{tone}} दिन हो।",
    en: "This is a {{tone}} day for the date you chose.",
  },
  "vastu.plot.construction_disclaimer": {
    ne: "ताराबल एक परम्परागत जाँच मात्र हो — भूमि पूजा वा निर्माण सुरु गर्ने मितिका लागि योग्य ज्योतिषीको सल्लाह पनि लिनुहोस्।",
    en: "Tara Bala is one traditional check among several — also consult a qualified astrologer before fixing a Bhoomi Puja or construction-start date.",
  },
  "vastu.plot.tone.best": { ne: "अति शुभ", en: "excellent" },
  "vastu.plot.tone.good": { ne: "शुभ", en: "good" },
  "vastu.plot.tone.neutral": { ne: "मध्यम", en: "neutral" },
