  "vastu.plot.tone.worst": { ne: "धेरै अशुभ", en: "very unfavorable" },

  "vastu.plan.requirements_heading": { ne: "घरमा चाहिने कोठाहरू", en: "House requirements" },
  "vastu.plan.requirements_blurb": {
    ne: "पहिले कति शयनकक्ष, शौचालय र अन्य कोठा चाहिन्छ भन्नुहोस्। त्यसपछि वास्तु अनुसार प्रत्येक कोठा कहाँ राख्ने सुझाव देखिन्छ — एउटा दिशामा मात्र बाँधिँदैन।",
    en: "First say how many bedrooms, toilets and other spaces you need. Then the planner suggests a zone for each — preferred, acceptable, or shared — not a single locked direction.",
  },
  "vastu.plan.bedrooms": { ne: "शयनकक्ष संख्या", en: "Number of bedrooms" },
  "vastu.plan.toilets": { ne: "शौचालय संख्या", en: "Number of toilets" },
  "vastu.plan.bathrooms": { ne: "स्नानघर संख्या", en: "Number of bathrooms" },
  "vastu.plan.combined": { ne: "शौचालय + स्नान एकै ठाउँ", en: "Combined toilet + bathroom" },
  "vastu.plan.wet_blurb": {
    ne: "शौचालय, स्नानघर र दुवै मिलेको कोठालाई वास्तुमा फरक ठाउँ मानिन्छ — त्यसैले छुट्टाछुट्टै सोधिएको हो।",
    en: "A toilet, a bathroom, and a combined toilet-bath are treated as different placements in Vastu, so they are asked separately.",
  },
  "vastu.plan.master_bedroom": { ne: "मुख्य शयनकक्ष कुन हो?", en: "Which is the master bedroom?" },
  "vastu.plan.bedroom_n": { ne: "शयनकक्ष {{n}}", en: "Bedroom {{n}}" },
  "vastu.plan.essential": { ne: "आवश्यक कोठा", en: "Essential spaces" },
  "vastu.plan.combine_kitchen_dining": { ne: "भान्सा र भोजन एउटै कोठामा (आधुनिक)", en: "Combine kitchen & dining (modern)" },
  "vastu.plan.combine_kitchen_dining_note": {
    ne: "शास्त्रीय वास्तुमा काठको आगोको धुवाँ र खरानीका कारण भान्सा र भोजन छुट्टै राखिन्थ्यो। ग्यास वा बिजुलीमा पकाउँदा त्यो समस्या हुँदैन, त्यसैले यसलाई आधुनिक विकल्पको रूपमा राखिएको छ — बाध्यकारी होइन।",
    en: "Classical Vastu keeps them separate because of wood-fire smoke and ash. Modern gas or electric cooking removes that concern, so combining is offered as a valid modern choice — not the default.",
  },
  "vastu.plan.optional": { ne: "थप कोठा", en: "Optional spaces" },
  "vastu.plan.mode_label": { ne: "वास्तु कति कडा राख्ने?", en: "Vastu preference" },
  "vastu.plan.mode.strict": { ne: "कडा वास्तु", en: "Strict Vastu" },
  "vastu.plan.mode.flexible": { ne: "लचिलो वास्तु", en: "Flexible Vastu" },
  "vastu.plan.mode.strict_hint": {
    ne: "कोठाहरू सिफारिस गरिएको दिशामा मात्र राखिन्छन् — ठाउँ पुगेन भने एउटै क्षेत्र बाँडिन्छ।",
    en: "Rooms stay in their recommended zones only. If those fill up, they share a zone rather than moving elsewhere.",
  },
  "vastu.plan.mode.flexible_hint": {
    ne: "सिफारिस ठाउँ भरिएपछि स्वीकार्य विकल्पमा सर्छ — अशुभ क्षेत्रमा राखिँदैन।",
    en: "When a recommended zone is full, the room may move to an acceptable alternative — never into an avoid zone.",
  },
  "vastu.plan.floor_heading": { ne: "कुन तल्लामा राख्ने?", en: "Which floor?" },
  "vastu.plan.floor_blurb": {
    ne: "केही कोठा तल्लामा बाँध्न चाहनुहुन्छ भने यहाँ भन्नुहोस् — ग्रिड अझै एउटै तल्लाको खाका हो।",
    en: "If a room must stay on a particular floor, say so here. The sketch is still a single-storey plan.",
  },
  "vastu.plan.storeys": { ne: "कति तल्ला?", en: "Number of floors" },
