  "learn.diagrams.graha_meaning_venus": { ne: "प्रेम, सौन्दर्य — शुक्रवार", en: "Love, beauty — Friday" },
  "learn.diagrams.gregorian_jump_caption": {
    ne: "जुलियन नियमको जम्मा भएको त्रुटि मिलाउन अक्टोबर १५८२ बाट दस दिन एकैचोटि हटाइयो — ४ गतेको भोलिपल्ट सिधै १५ गते भयो, र बीचका दस दिन कहीँ पनि अस्तित्वमा आएनन्। तर सबैले एकैचोटि अपनाएनन्, र त्रुटि चलिरहेकै हुनाले पछि अपनाउनेले झन् धेरै दिन हटाउनुपर्‍यो — बेलायतले ११, रुसले १३।",
    en: "Ten days were struck from October 1582 to clear the accumulated Julian error: the 4th was followed directly by the 15th, and the days between never existed anywhere. Adoption was not simultaneous, though, and because the error kept accruing, later adopters had to remove more days — eleven for Britain, thirteen for Russia.",
  },
  "learn.diagrams.gregorian_jump_label": {
    ne: "अक्टोबर १५८२ मा हटाइएका दस दिन, र देशैपिच्छे फरक अपनाउने साल",
    en: "The ten days removed from October 1582, and the staggered adoption that followed",
  },
  "learn.diagrams.gregorian_jump_lost_days": {
    ne: "१० दिन हटाइयो — यी कहिल्यै भएनन्",
    en: "ten days removed — these never happened",
  },
  "learn.diagrams.gregorian_jump_month": { ne: "अक्टोबर १५८२", en: "October 1582" },
  "learn.diagrams.hierarchy_caption": {
    ne: "तीन गति, तीन धारा, एउटा मिति। पृथ्वीको घुर्णनले दिन र वार, सूर्यको राशि–गतिले सङ्क्रान्ति र सौर महिना, चन्द्र–सूर्य कोणले तिथि, पक्ष र चान्द्र मास — बीचका दुई धारा नै सौरमान र चान्द्रमान हुन्, र तीनै मिलेर पञ्चाङ्ग बन्छ।",
    en: "Three motions, three streams, one date. Earth's spin gives the day and the vaara, the Sun's travel through the zodiac gives sankranti and the solar month, the Moon's angle from the Sun gives tithi, paksha and the lunar month — the middle two streams are exactly sauramāna and chāndramāna, and all three together make the panchanga.",
  },
  "learn.diagrams.hierarchy_converge": { ne: "पञ्चाङ्ग", en: "Panchanga" },
  "learn.diagrams.hierarchy_driver_earth": { ne: "आफ्नै अक्षमा घुर्णन", en: "spin on its own axis" },
  "learn.diagrams.hierarchy_driver_moon": { ne: "सूर्यसँगको कोणीय दूरी", en: "angular gap from the Sun" },
  "learn.diagrams.hierarchy_driver_sun": { ne: "राशिचक्रमा वार्षिक गति", en: "annual path through the zodiac" },
  "learn.diagrams.hierarchy_mana_lunar": { ne: "चान्द्रमान", en: "Chāndramāna" },
  "learn.diagrams.hierarchy_mana_solar": { ne: "सौरमान", en: "Sauramāna" },
  "learn.diagrams.hierarchy_result": { ne: "एउटा बि.सं. मिति", en: "One Bikram Sambat date" },
  "learn.diagrams.hierarchy_result_fields": {
    ne: "वर्ष · महिना · गते · तिथि · वार",
    en: "year · month · gate · tithi · vaara",
  },
  "learn.diagrams.hierarchy_rule_boundary": { ne: "सीमा पार", en: "boundary crossed" },
  "learn.diagrams.hierarchy_rule_month_count": { ne: "३० तिथि", en: "30 tithis" },
  "learn.diagrams.hierarchy_rule_one_turn": { ne: "१ फेरो", en: "1 turn" },
  "learn.diagrams.hierarchy_rule_paksha_count": { ne: "१५ तिथि", en: "15 tithis" },
