  "learn.study.calc.belt_lede_readouts": {
    ne: "को जाल — सूर्यको निरयन देशान्तर अनुसार कुन खण्ड उज्यालो हुन्छ हेर्नुहोस्। वर्ष स्लाइडर / चलाउनुहोस् ले सूर्यलाई पट्टीमा सार्छ; पढाइमा सूर्य राशि, नक्षत्र, तिथि कोण (चन्द्र−सूर्य) देखिन्छ — यही कोण सर्भरमा तिथि बनाउँछ।",
    en: "grid — watch which sector lights up from the Sun’s sidereal longitude. The year slider and play button move the Sun along the belt; the readouts show the Sun sign, the nakshatra, and the tithi angle (Moon − Sun) — the same angle the server turns into a tithi.",
  },
  "learn.study.calc.belt_lede_scene": {
    ne: "दृश्य हो: पृथ्वी बीचमा, सूर्य दूर (दिशा मात्र), चन्द्रको कक्ष, र बाहिर",
    en: "teaching view: Earth at the centre, the Sun as a direction only, the Moon’s orbit, and an outer",
  },
  "learn.study.calc.belt_note": {
    ne: "यो चित्र शिक्षाका लागि सरलीकृत कक्ष हो; उत्पादनमा स्विस एफेमेरिसले जेपीएल ग्रहपात, अपवर्तन र अवलोककको उचाइ प्रयोग गर्छ।",
    en: "The orbits here are simplified for teaching; in production Swiss Ephemeris uses the JPL ephemeris, refraction, and the observer’s elevation.",
  },
  "learn.study.calc.belt_title": { ne: "पृथ्वी, कक्षा र राशि–नक्षत्र पट्टी", en: "Earth, ecliptic & the rashi belt" },
  "learn.study.calc.col_calc": { ne: "गणना", en: "Calculation" },
