  "learn.study.eclipse.caption_nodes_drift": {
    ne: "भने आकाशमा बिस्तारै घडीको दिशामा घुम्छन् (~{{perYear}}°/वर्ष, ~{{years}} वर्षे पूरा चक्र) — चन्द्रभन्दा लगभग {{factor}} गुणा ढिलो।",
    en: "drift slowly clockwise across the sky (~{{perYear}}°/year, a full cycle in ~{{years}} years) — roughly {{factor}} times slower than the Moon.",
  },
  "learn.study.eclipse.caption_when": {
    ne: "ग्रहण तब हुन्छ जब पूर्णिमा/औंसी पात रेखा नजिक पर्छ — वर्षमा झन्डै दुई पटक ({{lunar}} चन्द्र, {{solar}} सूर्य यस चक्रमा)।",
    en: "An eclipse happens when a full moon or new moon falls near that node line — roughly twice a year ({{lunar}} lunar, {{solar}} solar in this cycle).",
  },
  "learn.study.eclipse.day_lunar_month": { ne: "दिन · चान्द्र महिना", en: "Day · lunar month" },
