  "learn.study.precession.caption_cycle": {
    ne: "वरिपरि बिस्तारै घुम्छ — पूरा एक फेरो ~{{years}} वर्ष। त्यसैले उत्तर ध्रुवले फरक-फरक",
    en: "— one full turn takes about {{years}} years. That is why the north pole keeps pointing at a different",
  },
  "learn.study.precession.caption_lead": {
    ne: "पृथ्वीको अक्ष {{tilt}}° झुकेरै रहन्छ तर लठ्ठाझैँ",
    en: "Earth’s axis stays tilted at {{tilt}}° but, like a spinning top, slowly circles the",
  },
  "learn.study.precession.caption_stars": {
    ne: "देखाउँछ — कुनै बेला थुबन, अहिले ध्रुव, र ~{{year}} बि.सं. मा अभिजित। ऋतु-आधारित",
    en: "over time — Thuban once, Polaris today, and Vega around {{year}} BS. The season-based",
  },
  "learn.study.precession.caption_tail": {
    ne: "राशिचक्रमा घुम्दै जान्छ — यही अयन चलन ले माथिको अयनांश खाँडो बढाउँछ।",
    en: "keeps sliding around the zodiac — this precession is what widens the ayanamsha gap shown above.",
  },
  "learn.study.precession.cycle_years": { ne: "{{years}} वर्ष", en: "{{years}} years" },
