  "learn.study.ritu.aria": {
    ne: "छ ऋतु, बाह्र महिना र चार सायन बिन्दु एउटै चक्रमा",
    en: "The six ṛtus, twelve months and four tropical markers on one wheel",
  },
  "learn.study.ritu.caption": {
    ne: "ऋतुको नाम महिनाले दिन्छ, तर ऋतु बनाउने कुरा सूर्यको उत्तर–दक्षिण यात्रा हो। दुई फरक ढाँचा भएकाले चारै सायन बिन्दु (हरियो = विषुव, सुन्तला = अयनान्त) महिनाको सीमामा नभई बीचमा पर्छन् — ग्रीष्म अयनान्त असारभित्र, जेठ–असारको सन्धिमा होइन। अयन चलनले हरेक ७२ वर्षमा १° का दरले यी बिन्दु सार्दै लैजान्छ; त्यसैले ऋतुको कुरा गर्दा महिना होइन, उत्तरायण–दक्षिणायन नै भरपर्दो सन्दर्भ हो।",
    en: "The ṛtus take their names from the months, but what makes a ṛtu is the Sun's north–south journey. Because those are two different frames, all four tropical markers (green = equinox, amber = solstice) fall inside a month rather than on its boundary — the summer solstice sits within Asar, not at the Jestha–Asar seam. Precession moves these markers 1° every 72 years, which is why the dependable reference for a ṛtu argument is Uttarāyaṇa and Dakṣiṇāyana, not the months.",
  },
  "learn.study.ritu.grishma": { ne: "ग्रीष्म", en: "Grīṣma" },
  "learn.study.ritu.hemanta": { ne: "हेमन्त", en: "Hemanta" },
  "learn.study.ritu.sharad": { ne: "शरद्", en: "Śarad" },
  "learn.study.ritu.shishira": { ne: "शिशिर", en: "Śiśira" },
  "learn.study.ritu.six_ritus": { ne: "छ ऋतु", en: "Six ṛtus" },
  "learn.study.ritu.two_months_each": { ne: "प्रत्येक दुई महिना", en: "two months each" },
  "learn.study.ritu.varsha": { ne: "वर्षा", en: "Varṣā" },
  "learn.study.ritu.vasanta": { ne: "वसन्त", en: "Vasanta" },
  "learn.study.sem.caption_adhika_masa": { ne: "अधिक मास", en: "Adhika Masa" },
  "learn.study.sem.caption_drift": {
    ne: "देखाउँछ — सूर्य नयाँ राशि वा नक्षत्रमा प्रवेश गर्दा ग्रिड सीमा पार हुन्छ (सङ्क्रान्ति)। पृथ्वीले सूर्यको १ फेरो (~{{yearDays}} दिन) लगाउँदा चन्द्रले ~{{moonLaps}} फेरो लगाउँछ — त्यसैले १२ चान्द्र महिना सकिँदा वर्ष ~{{remainingDays}} दिन बाँकी रहन्छ, जसले",
    en: "as seen from Earth — when the Sun enters a new rashi or nakshatra it crosses a grid boundary (sankranti). While Earth makes one orbit of the Sun (~{{yearDays}} days) the Moon makes ~{{moonLaps}} orbits — so after twelve lunar months about {{remainingDays}} days of the year are left over, which gives rise to",
  },
  "learn.study.sem.caption_lead": {
    ne: "बाहिरी {{rashis}} राशि र {{nakshatras}} नक्षत्रको ग्रिडले पृथ्वीबाट देखिने",
    en: "The outer grid of {{rashis}} rashis and {{nakshatras}} nakshatras shows the",
  },
